void Solver::restart() {
    // Aggressively reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;
    for (int i = 0; i < 50; ++i) lbd_queue[i] = 0;

    // Backtrack to root level
    backtrack(0);

    // Re‑phase variables with a mixed strategy
    int mode = rand() % 100;
    if (mode < 40) {
        // Keep the best phase found so far
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (mode < 70) {
        // Invert the best phase
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else if (mode < 90) {
        // Assign random polarity
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    } else {
        // Bias towards variables with high activity
        for (int i = 1; i <= vars; ++i) {
            saved[i] = (activity[i] > 0.5 * var_inc) ? 1 : -1;
        }
    }
}
